import 'package:flutter/material.dart';import '../data/app_database.dart';
class SalesPage extends StatefulWidget{const SalesPage({super.key});@override State<SalesPage> createState()=>_S();}
class _S extends State<SalesPage>{List<Map<String,Object?>> products=[];final cart=<Map<String,Object?>>[];@override void initState(){super.initState();load();}Future<void> load()async{products=await AppDatabase.instance.listProducts();if(mounted)setState((){});}void add(Map<String,Object?> p){setState((){final i=cart.indexWhere((x)=>x['product_id']==p['id']);if(i>=0){cart[i]['qty']=((cart[i]['qty'] as num)+1).toDouble();}else{cart.add({'product_id':p['id'],'product_name':p['name'],'qty':1.0,'price':(p['price'] as num).toDouble()});}});}Future<void> save()async{if(cart.isEmpty)return;final inv=await AppDatabase.instance.createSale(items:cart);cart.clear();await load();if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$inv saved')));}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Sales & Invoice')),body:Column(children:[Expanded(child:ListView.builder(itemCount:products.length,itemBuilder:(_,i){final p=products[i];return ListTile(title:Text('${p['name']}'),subtitle:Text('Stock: ${p['stock']} • Price: ${p['price']}'),trailing:IconButton(onPressed:()=>add(p),icon:const Icon(Icons.add_shopping_cart)));})),Container(padding:const EdgeInsets.all(12),child:Column(children:[const Row(children:[Expanded(flex:4,child:Text('Product')),Expanded(child:Text('Qty')),Expanded(child:Text('Price')),Expanded(child:Text('Total'))]),const Divider(),...cart.map((x)=>Row(children:[Expanded(flex:4,child:Text('${x['product_name']}')),Expanded(child:Text('${x['qty']}')),Expanded(child:Text('${x['price']}')),Expanded(child:Text('${(x['qty'] as num)*(x['price'] as num)}'))])),const SizedBox(height:8),SizedBox(width:double.infinity,child:FilledButton(onPressed:cart.isEmpty?null:save,child:const Text('Save Invoice')))]))]));}
